    const px = 1040, py = 760, pw = 700, ph = 440, xS = e => px + e * pw, yS = v => py - v / 0.38 * ph;
    plotFrame128(px, py, pw, ph, tq, 'E / V₀', 'T(E)   (μ = V₀ = ħ = 1 , a = 2)');
