    chip(1370, 350, 800, 56, 'p_s = 1/5 for every s ;  (X, Y, Z) = (2/5 , 2/5 , 1/5)', C.cyan, Q(S, 0, 'keep all five probabilities at one fifth', 0.6) * f1, 20);
