    items.forEach(([a1, a2, col, ph], i) => { const x = 230 + (i % 5) * 365, y = 230 + Math.floor(i / 5) * 150, q = Q(S, 0, ph) * fade; box(x - 160, y, 320, 125, col, q, 2, 'rgba(0,0,0,0.5)'); lbl(a1, x, y + 48, col, q, 20); lblG(a2, x, y + 95, C.white, q, 21); });
    lbl('CLASSICAL · two-body separation (Fitzpatrick) · rectangular barrier (Tong §2.4.2) · Bell correlations · closed forms and variational principle (Teschl)', W / 2, 590, '#8fbcff', Q(S, 1, 'The two-body separation') * fade, 14);
